Translate("deDE", "elwynn-forest", {
	title = "Wald von Elwynn",
	aliases = { "Elwynn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Wald von Elwynn ist das grüne Herz des {link:kingdom-of-stormwind}Königreichs Stormwind{/link}. Seine Eichen drängen sich dicht um die weißen Mauern der {link:capital-city}Hauptstadt{/link}, und zwischen ihnen liegen stille Seen, goldene Felder und alte Minen, die das Königreich seit Generationen ernähren. Für die Leute von {link:stormwind-city}Stormwind{/link} war Elwynn immer der sicherste Ort der Welt. Dieser Glaube bröckelt nun. Wölfe streifen mit jeder Jahreszeit näher an die Höfe heran, seltsame Dinge regen sich in den Minen, und die Straßen, die einst nur Händler und Pilger kannten, kennen nun Diebe.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem sich die ersten {link:humans}Menschen{/link} in Elwynn niederließen. Bekannt ist, dass der Wald viele Jahrhunderte vor der Öffnung des {link:dark-portal}Dunklen Portals{/link} in Besitz genommen wurde. Als das alte Reich von {link:arathor}Arathor{/link} seine lange Einheit verlor, zogen kühne Familien aus der Blutlinie der {link:arathi-highlands}Arathi{/link} nach Süden, auf der Suche nach neuem Land. Zwischen den reichen Wäldern und Flüssen, die sie dort fanden, errichteten sie ein Königreich, das sie {link:azeroth}Azeroth{/link} nannten, und in seinem Herzen eine Stadt namens {link:stormwind-city}Stormwind{/link}. Elwynn wurde die Kornkammer und der Garten des Reiches. Nördlich der Stadt pflegten die Kleriker der {link:northshire-abbey}Abtei von Nordhain{/link} den Glauben an das {link:holy-light}Heilige Licht{/link}, und ihre Abtei wurde eine seiner ältesten Heimstätten im Süden.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Elwynn ist aus der Asche des Krieges nachgewachsen, doch es ist schlecht bewacht. König {link:varian-wrynn}Varian Wrynn{/link} ist verschwunden, und niemand kann sagen, wohin. In seiner Abwesenheit herrscht Hochlord {link:bolvar-fordragon}Bolvar Fordragon{/link} als Regent, und die Stärke des Reiches ist dünn über ein Dutzend unruhiger Grenzen verteilt. {link:kobolds}Kobolde{/link} haben die {link:fargodeep-mine}Tiefenschachtmine{/link} und die {link:jasperlode-mine}Jaspismine{/link} besetzt. {link:riverpaw-gnolls}Gnolle der Flusspfoten{/link} fallen über die Südgrenze ein. Banditen der {link:defias-brotherhood}Bruderschaft der Defias{/link} machen Jagd auf die Höfe nahe {link:westfall}Westfall{/link}. Die wenigen Marschälle von {link:goldshire}Goldhain{/link} können den Wald nicht mehr allein halten, und sie heißen jedes Schwert willkommen, das zu dienen bereit ist.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Das Volk von {link:stormwind-city}Stormwind{/link}.{/b} Bauern, die Holzfäller des Osttals und die Bergleute der Hügel bleiben, weil das Land gut ist und weil sie nirgendwo anders hinkönnen.
• {b}Die Geistlichen und Rekruten von {link:northshire-abbey}Nordhain{/link}.{/b} In der Abtei bilden Priester und Paladine die jungen Männer und Frauen aus, die das Königreich verteidigen werden.
• {b}{link:kobolds}Kobolde{/link}.{/b} Sie graben sich in die Minen. Sie fürchten die Dunkelheit über alles und hüten ihre Kerzen mit wilder Hingabe.
• {b}Die {link:riverpaw-gnolls}Gnolle der Flusspfoten{/link}.{/b} Sie kommen aus den südlichen Hügeln und aus dem {link:redridge-mountains}Rotkammgebirge{/link} herab, hungrig nach Nahrung und Beute.
• {b}Die {link:defias-brotherhood}Bruderschaft der Defias{/link}.{/b} Ihre Reihen begannen mit Männern, die einst Stormwind wieder aufbauten und die sich nun mit dem Messer nehmen, was die Krone ihnen ihrer Meinung nach noch schuldet.
• {b}Murlocs.{/b} Die Stämme der {link:murlocs}Murlocs{/link} suchen die Ufer des Kristallsees und des Steinhügelsees heim, seit Menschengedenken.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der lange Frieden.{/b} Generationenlang kannte Elwynn wenig außer Ernte und Fest. Seine Dörfer wurden reich durch den Handel, der durch {link:stormwind-city}Stormwind{/link} floss.
• {b}Der Erste Krieg.{/b} Dann kam die orcische {link:horde}Horde{/link} durch das Dunkle Portal, und die Länder von {link:azeroth}Azeroth{/link} brannten als Erste. Im {link:first-war}Ersten Krieg{/link} setzte die Horde die Höfe und Wälder Elwynns in Brand, und selbst die heiligen Hallen der {link:northshire-abbey}Abtei von Nordhain{/link} entgingen den Flammen nicht. Zuletzt wurde Stormwind selbst geplündert, und König {link:llane-wrynn}Llane Wrynn{/link} wurde in seiner eigenen Burg erschlagen. Sir {link:anduin-lothar}Anduin Lothar{/link} führte die Überlebenden nach Norden über das Meer nach {link:lordaeron}Lordaeron{/link}, und mit ihnen ging der junge Sohn des Königs, {link:varian-wrynn}Varian{/link}.
• {b}Die Rückkehr.{/b} Nach dem {link:second-war}Zweiten Krieg{/link} kehrten die Verbannten heim. Sie pflanzten den Wald neu und bauten die Dörfer wieder auf. Die {link:stonemasons-guild}Steinmetzgilde{/link} unter {link:edwin-vancleef}Edwin VanCleef{/link} errichtete Stormwind neu aus seinen Trümmern. Als das {link:house-of-nobles}Haus der Adligen{/link} sich weigerte, die Steinmetze für ihre Arbeit zu bezahlen, erhoben sich die Steinmetze in den Straßen. Königin {link:tiffin-wrynn}Tiffin Wrynn{/link} war unter denen, die in dem Chaos starben. Die Steinmetze wurden aus der Stadt vertrieben, und aus ihrer Verbitterung wurde die {link:defias-brotherhood}Bruderschaft der Defias{/link} geboren.
• {b}Die Gegenwart.{/b} Nun ist der König fort, die Heere sind weit entfernt, und Elwynn hofft auf den Mut einer Handvoll Marschälle und Freiwilliger.]=],
		},
		{
			title = "Überlieferungen des Waldes",
			text = [=[• Unter den Kobolden von Elwynn gibt es kein größeres Verbrechen, als eine Kerze zu stehlen. Jeder Bergmann, der unter Tage gearbeitet hat, kennt den Schrei, der auf einen solchen Diebstahl folgt.
• Die Familien Maclure und Stonefield liegen über denselben Zaun hinweg in Fehde, länger als sich beide erinnern können. Doch das Geflüster in {link:goldshire}Goldhain{/link} sagt, dass sich eine Tochter der Maclures und ein Sohn der Stonefields heimlich treffen, wenn die Felder dunkel sind.
• Der {link:tower-of-azora}Turm von Azora{/link} erhebt sich im Osten des Waldes. Er ist die Heimat eines Magiers, dessen Studien das einfache Volk von Elwynn weder versteht noch erfragen möchte.
• Die Bauern des Südens sprechen mit gedämpfter Stimme von {link:hogger}Hogger{/link}. Er ist ein {link:gnolls}Gnoll{/link}, so groß und so listig, dass das Kopfgeld auf ihn viele Jahreszeiten lang nicht eingelöst wurde.]=],
		},
	},
})

Translate("deDE", "northshire-abbey", {
	title = "Abtei von Nordhain",
	aliases = { "Nordhain" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Abtei von Nordhain steht am oberen Ende eines geschützten Tals nördlich von {link:stormwind-city}Stormwind{/link}. Seit Jahrhunderten ist sie ein Haus des Heiligen Lichts, in dem Kleriker beteten, heilten und die alten Bücher ihres Glaubens hüteten. Hier lag der junge {link:medivh}Medivh{/link} jahrelang in einem Schlaf, den kein Heiler brechen konnte, gepflegt von den Brüdern der Abtei. Im Ersten Krieg brannte die {link:horde}Horde{/link} sie nieder, doch die Gläubigen kehrten zurück und errichteten ihre Mauern von Neuem. Heute ist sie ein Ausbildungsort. Rekruten kommen, um Schwert, Zauber und Gebet zu lernen, bevor man sie hinaus in einen Wald schickt, der sie braucht.]=],
		},
		{
			title = "Das Tal",
			text = [=[Das Tal ist nicht mehr still. {link:kobolds}Kobolde{/link} haben sich in die Echokammmine oberhalb der Abtei gegraben. Diebe mit roten Halstüchern lauern zwischen den Reben der Weinberge von Nordhain, und ihr Anführer hat eine Hütte am Ostrand des Tals. Wölfe kommen aus den Hügeln herab. Die Brüder von Nordhain haben gelernt, dass selbst heiliger Boden bewacht werden muss.]=],
		},
	},
})

Translate("deDE", "goldshire", {
	title = "Goldhain",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Goldhain ist die Wegkreuzung von {link:elwynn-forest}Elwynn{/link}. Seine Straßen führen nach Norden zur Abtei, nach Süden zu den Höfen, nach Osten zu den Holzfällerlagern und nach Westen Richtung {link:westfall}Westfall{/link}. In seinem Herzen steht das Lion's Pride Inn, wo die Familie Farley Reisenden Bier ausschenkt, solange sich die ältesten Leute des Ortes erinnern können. Der Ort hat einen Schmied, einen Stall und einen Apotheker. Er ist auch der Posten von {link:marshal-dughan}Marschall Dughan{/link}, dessen wenige Soldaten für die Sicherheit des ganzen Waldes geradestehen müssen.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Das Gasthaus ist laut vor Gerüchten. Händler sprechen von Goldstaub, der aus den Minen gekauft wird, von {link:murlocs}Murlocs{/link}, die an den Seeufern kühn geworden sind, von Gnollen an der Südstraße. Die Ältesten von Goldhain erinnern sich noch an den Rauch des Ersten Krieges. Die Jüngeren beginnen zu begreifen, was ihre Ältesten meinten.]=],
		},
	},
})

Translate("deDE", "fargodeep-mine", {
	title = "Tiefenschachtmine",
	aliases = { "Tiefenschacht" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Tiefenschacht war einst eine Goldmine der Krone. Er liegt in den südlichen Hügeln von {link:elwynn-forest}Elwynn{/link}, zwischen den Ländereien der Stonefields und der Maclures. Als die Bergleute ihn verließen, kamen die {link:kobolds}Kobolde{/link}. Nun flackern in seinen Stollen die Kerzen eines Koboldbaus, und man sagt, dass der Kobold {link:goldtooth}Goldtooth{/link} in seinen Tiefen gestohlene Schätze hortet. Worauf auch immer die Kobolde hingraben, sie graben mit Eifer.]=],
		},
	},
})

Translate("deDE", "jasperlode-mine", {
	title = "Jaspismine",
	aliases = { "Jaspis" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Jaspismine liegt in den östlichen Hügeln, nördlich des Turms von {link:tower-of-azora}Azora{/link}. Sie war eine der Minen, die die Schmieden von {link:stormwind-city}Stormwind{/link} speisten. {link:kobolds}Kobolde{/link} halten nun ihre oberen Stollen. Noch tiefer, wohin selbst die Kobolde nicht freiwillig gehen, spinnen große Minenspinnen im Dunkeln ihre Netze. Die Bergleute, die aus der Jaspismine flohen, sprechen mehr von den Spinnen als von den Kobolden.]=],
		},
	},
})

Translate("deDE", "tower-of-azora", {
	title = "Turm von Azora",
	aliases = { "Azora" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Turm von Azora erhebt sich über den östlichen Wäldern von {link:elwynn-forest}Elwynn{/link}. Er ist der Sitz des Magiers {link:theocritus}Theocritus{/link} und der {link:gnomes}Gnome{/link}, die ihm dienen. Aus seiner höchsten Kammer blickt eine Späheinrichtung namens Auge von Azora weit nach Osten, zum {link:tower-of-ilgalar}Turm von Ilgalar{/link} im {link:redridge-mountains}Rotkammgebirge{/link}. Dort haust der Hexenmeister {link:morganth}Morganth{/link}, dessen dunkle Studien Theocritus zu beobachten und zu vereiteln geschworen hat. Die Leute des Waldes halten sich von beiden Türmen fern.]=],
		},
	},
})

Translate("deDE", "brackwell-pumpkin-patch", {
	title = "Brackwells Kürbisbeet",
	aliases = { "Brackwell" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Hof der Brackwells liegt im Südosten von {link:elwynn-forest}Elwynn{/link}, wo einst eine Familie Kürbisse zog, die im ganzen Wald berühmt waren. Die Brackwells sind fort, und niemand kann sagen, was aus ihnen wurde. Die {link:defias-brotherhood}Bruderschaft der Defias{/link} hält den Hof nun. Man sagt, dass Gold aus den Koboldminen auf seinem Weg zu einem Agenten der Defias, den man den Sammler nennt, hier durchkommt. Nur ein Schatz der Brackwells ist geblieben: Princess, ihre preisgekrönte Sau, die von den Gemüsen ihrer Nachbarn gewaltig geworden ist.]=],
		},
	},
})

Translate("deDE", "eastvale-logging-camp", {
	title = "Holzfällerlager des Osttals",
	aliases = { "Osttal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Osttal ist das Holzfällerlager von {link:elwynn-forest}Elwynn{/link}, am Ostrand des Waldes nahe der Straße ins {link:redridge-mountains}Rotkammgebirge{/link}. Seine Holzfäller liefern das Bauholz, mit dem {link:stormwind-city}Stormwind{/link} wieder aufgebaut wurde, und sie schicken noch immer jede Jahreszeit Wagen nach Westen. Das Lager lebt unter ständiger Bedrohung durch Wölfe und Bären. {link:guard-thomas}Wachmann Thomas{/link} hält die Brücke im Westen, und das alte Landhaus von {link:marshal-haggard}Marschall Haggard{/link} steht in der Nähe.]=],
		},
	},
})

Translate("deDE", "stone-cairn-lake", {
	title = "Der Steinhügelsee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Steinhügelsee ist ein Ring aus Wasser um eine bewaldete Insel im Nordosten des Waldes. An seinem Ufer liegt die Heldenwache, wo ein Steinhügel an die Männer und Frauen von {link:goldshire}Goldhain{/link} und seinen Höfen erinnert, die im Ersten Krieg starben. Es ist ein Ort der Trauer. Ein Ort des Friedens ist er nicht mehr: Abtrünnige Zauberer haben die Insel eingenommen, und {link:murlocs}Murlocs{/link} jagen am Südufer.]=],
		},
	},
})

Translate("deDE", "maclure-vineyards-and-stonefield-farm", {
	title = "Weinberge der Maclures und Hof der Stonefields",
	aliases = { "Weinberge der Maclures", "Hof der Stonefields" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Im Süden von {link:elwynn-forest}Elwynn{/link} liegen zwei Höfe zu beiden Seiten eines schmalen Landstreifens. Im Osten wachsen die Reben der Maclures. Im Westen stehen die Felder und das Haus der Stonefields. Die beiden Familien liegen im Krieg, länger als sich irgendeines ihrer Kinder erinnern kann, und der Grund liegt längst unter Beleidigungen, gestohlenen Gütern und zugeschlagenen Türen begraben. Doch zwischen Weinberg und Hof verläuft ein stiller Pfad, und nicht jeder, der ihn geht, geht ihn im Zorn.]=],
		},
	},
})

Translate("deDE", "crystal-lake", {
	title = "Kristallsee",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Kristallsee liegt östlich von {link:goldshire}Goldhain{/link}, still und klar wie sein Name. Sein Wasser nährt einen seltenen Seetang, der wie Glas glitzert und von Apothekern wegen seiner seltsamen Eigenschaften geschätzt wird. Die {link:murlocs}Murlocs{/link} des Sees bewachen ihn eifersüchtig. Fischer, die hier einst ihre Netze auswarfen, halten sich nun ans ferne Ufer.]=],
		},
	},
})

Translate("deDE", "westbrook-garrison", {
	title = "Weststromgarnison",
	aliases = { "Weststrom" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Weststromgarnison bewacht den Westrand von {link:elwynn-forest}Elwynn{/link}, wo der Wald in die Felder von {link:westfall}Westfall{/link} übergeht. Ihre Kaserne wurde gebaut, um den Frieden der Grenze zu wahren. Nun kämpft sie darum, überhaupt irgendetwas zu wahren. Diebe kommen aus dem Westen, und die {link:riverpaw-gnolls}Gnolle der Flusspfoten{/link} vom Waldrand fallen aus dem Süden ein. Am Anschlagbrett der Garnison hängt ein Aushang, den jeder Soldat auswendig kennt: eine Belohnung für den Kopf von {link:hogger}Hogger{/link}.]=],
		},
	},
})

Translate("deDE", "marshal-mcbride", {
	title = "Marschall McBride",
	subtitle = "Marschall von Nordhain",
	found = "In der Abtei von Nordhain",
	hint = [=[Sprecht mit dem Marschall, der die Rekruten von Nordhain befehligt.]=],
	allegiance = "Königreich Stormwind · Armee von Stormwind",
	aliases = { "McBride" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marschall Douglas McBride befehligt die Rekruten der {link:northshire-abbey}Abtei von Nordhain{/link}. Jeder neue Verteidiger Stormwinds geht zuerst durch seine Hände. Er muss aus Bauernsöhnen und Schreiberstöchtern Soldaten machen, und er muss es tun, während die Armee des Königreichs weit entfernt ist und {link:stranglethorn-vale}das Tal{/link} selbst bedroht wird.]=],
		},
		{
			title = "Bedeutung",
			text = [=[McBride ist der erste Offizier Stormwinds, dem die meisten neuen Rekruten je begegnen. Er sieht klar, was der Hof in der {link:capital-city}Hauptstadt{/link} nicht laut sagen will: Da die Armee in der Fremde steht, sind die Gesetzlosen daheim kühn geworden, und das Kernland des Königreichs muss von seinen neuesten und am wenigsten erprobten Leuten verteidigt werden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bildet die Rekruten von {link:northshire-abbey}Nordhain{/link} aus und prüft sie an den Gefahren des Tals.
• Er schickt Patrouillen gegen die {link:kobolds}Kobolde{/link} der Echokammmine.
• Er schreibt die Berichte, die Nachrichten über Kobolde, Diebe und Wölfe von Nordhain nach {link:goldshire}Goldhain{/link} tragen.]=],
		},
	},
	chapters = {
		{
			title = "Die Kobolde vom Echokamm",
			hint = "Treibt die Kobolde zurück in die Tiefen der Echokammmine.",
			text = [=[Die ersten {link:kobolds}Kobolde{/link} waren ein Ärgernis, das man mit Fackeln verjagte. Dann kehrten die Rekruten aus der Echokammmine mit Berichten von ganzen Bauten unter dem Tal zurück. McBride begann sich zu fragen, wie lange die Kobolde dort schon gruben und worauf sie sonst noch stoßen könnten.]=],
		},
		{
			title = "Papiere für Goldhain",
			hint = "Bringt die Dokumente des Marschalls nach Goldhain.",
			text = [=[Die Papiere, die McBride für {link:goldshire}Goldhain{/link} versiegelt, erzählen die Geschichte des Tals in schlichten Soldatenworten: {link:kobolds}Kobolde{/link} am Echokamm, eine Bruderschaft von Dieben mit roten Halstüchern und Wölfe, die aus dem Osten vertrieben wurden. Sie enthalten auch sein Urteil über den Rekruten, der sie trägt. Wer für würdig befunden wird, wird zum Hilfssheriff der Marschälle von {link:stormwind-city}Stormwind{/link} ernannt.]=],
		},
	},
	mentions = {
		{ text = "Eine Bedrohung von innen" },
		{ text = "Säuberung des Koboldlagers" },
		{ text = "Untersucht den Echokamm" },
		{ text = "Scharmützel am Echokamm" },
		{ text = "Meldet Euch in {link:goldshire}Goldhain{/link}" },
		{
			text = [=[Das große Ganze, die gestohlenen Bücher von {link:northshire-abbey}Nordhain{/link}]=],
		},
		{ text = "Folgt dem {link:kobolds}Kobold{/link}!" },
		{ text = "Ein gekritzelter Brief" },
		{ text = "Der Abenteurer" },
	},
	bonds = {
		{ id = "deputy-willem", name = "Hilfssheriff Willem", note = "hütet das Tor der Abtei" },
		{ id = "brother-paxton", name = "Bruder Paxton", note = "hütet die Bibliothek der Abtei" },
		{ id = "tordrin-sternblade", name = "Tordrin Sternblade", note = "der Jäger, den er Dieben nachschickt" },
		{ id = "marshal-dughan", name = "Marschall Dughan", note = "empfängt seine Rekruten" },
		{ id = "brother-sammuel", name = "Bruder Sammuel", note = "bildet die Paladine der Abtei aus" },
	},
})

Translate("deDE", "deputy-willem", {
	title = "Hilfssheriff Willem",
	subtitle = "Hilfssheriff von Nordhain",
	found = "Vor den Toren der Abtei von Nordhain",
	hint = [=[Sprecht mit dem Hilfssheriff, der vor den Toren der Abtei steht.]=],
	allegiance = "Königreich Stormwind · Armee von Stormwind",
	aliases = { "Willem" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hilfssheriff Willem hält Wache vor den Toren der {link:northshire-abbey}Abtei von Nordhain{/link}. Er begrüßt jeden Rekruten, der ankommt, und oft ist er der Erste, der ihnen sagt, wie dringend {link:stranglethorn-vale}das Tal{/link} ihre Hilfe braucht. Er würde lieber selbst draußen die Diebe jagen, doch sein Posten ist an der Tür.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Willem ist für viele junge Verteidiger das erste Gesicht des Dienstes für {link:stormwind-city}Stormwind{/link}. Durch ihn erfahren sie von den Dieben mit den roten Halstüchern, die sich ins Tal geschlichen haben.]=],
		},
		{
			title = "Taten",
			text = [=[• Er setzt einen Preis auf die roten Halstücher der Diebe in den Weinbergen von {link:northshire-abbey}Nordhain{/link} aus.
• Er setzt ein Kopfgeld auf den Dieb {link:garrick-padfoot}Garrick Padfoot{/link} aus.
• Er schickt Rekruten zu dem Jäger Eagan Peltskinner und zu der Winzerin {link:milly-osworth}Milly Osworth{/link}.]=],
		},
	},
	mentions = {
		{ text = "Eine Bedrohung von innen" },
		{ text = "Bruderschaft der Diebe" },
		{ text = "Kopfgeld auf {link:garrick-padfoot}Garrick Padfoot{/link}" },
		{ text = "Eagan Peltskinner" },
		{ text = "{link:milly-osworth}Milly Osworth{/link}" },
	},
	bonds = {
		{ id = "marshal-mcbride", name = "Marschall McBride", note = "sein Kommandant" },
		{ id = "garrick-padfoot", name = "Garrick Padfoot", note = "der Dieb, den er gefasst sehen will" },
