Translate("deDE", "marshal-dughan", {
	title = "Marschall Dughan",
	subtitle = "Marschall von Goldhain",
	found = "Goldhain, vor dem Lion's Pride Inn",
	hint = "Sprecht mit dem Marschall, der über Goldhain wacht.",
	allegiance = "Königreich Stormwind · Armee von Stormwind",
	aliases = { "Dughan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Von der Wegkreuzung {link:goldshire}Goldhain{/link} aus befehligt Marschall Dughan die Verteidigung des Waldes von {link:elwynn-forest}Elwynn{/link}. Seine Soldaten sind zu wenige für die Aufgabe. Dennoch muss er die Straßen offen halten, die die {link:capital-city}Hauptstadt{/link} mit ihren Höfen, ihren Mühlen und ihren Minen verbinden. Jeder Rekrut, der die {link:northshire-abbey}Abtei von Nordhain{/link} verlässt, geht durch seine Hände, und er schickt jeden dorthin, wo der Wald am schlimmsten blutet.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Dughan ist das Gesicht eines Königreichs, das bis an seine Grenzen gespannt ist. {link:stormwind-city}Stormwind{/link} hat keinen König auf dem Thron, kein Heer in der Nähe und nur die Treue gewöhnlicher Männer und Frauen, um seinen Frieden zu wahren. Er beklagt sich nicht darüber. Er tut einfach die Arbeit, die bleibt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hält {link:elwynn-forest}Elwynn{/link} mit einer Handvoll Soldaten, verteilt auf {link:goldshire}Goldhain{/link}, die {link:westbrook-garrison}Weststromgarnison{/link} und das {link:eastvale-logging-camp}Osttal{/link}.
• Er schickt Kundschafter in die {link:fargodeep-mine}Tiefenschachtmine{/link} und die {link:jasperlode-mine}Jaspismine{/link}, wo die {link:kobolds}Kobolde{/link} jeden Tag kühner werden.
• Er setzt ein Kopfgeld auf den {link:gnolls}Gnoll{/link} {link:hogger}Hogger{/link} und auf die Plünderer der {link:riverpaw-gnolls}Flusspfoten{/link} an der Südgrenze aus.
• Er schickt den abgelegenen Posten des Waldes, was er an Hilfe erübrigen kann, auch wenn er selten etwas übrig hat.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Dughans Leben vor {link:goldshire}Goldhain{/link} geschrieben. Dieser Eintrag verzeichnet nur, was seine Taten und sein Posten verraten.]=],
		},
	},
	chapters = {
		{
			title = "Die Rekruten von Nordhain",
			hint = [=[Beendet Eure Ausbildung in Nordhain und meldet Euch in Goldhain.]=],
			text = [=[Die Rekruten kommen mit Briefen von {link:marshal-mcbride}Marschall McBride{/link}. Dughan hat wenig Zeit, sie zu begrüßen, denn {link:kobolds}Kobolde{/link} halten die Minen, {link:gnolls}Gnolle{/link} streifen an der Grenze umher und Diebe suchen jede Straße heim. Er stellt jeden Neuankömmling binnen einer Stunde zur Arbeit ab.]=],
		},
		{
			title = "Unter den Hügeln",
			hint = "Untersucht im Auftrag des Marschalls die Minen von Elwynn.",
			text = [=[Die Berichte aus der {link:fargodeep-mine}Tiefenschachtmine{/link} und der {link:jasperlode-mine}Jaspismine{/link} bestätigen, was Dughan befürchtet hat. Die {link:kobolds}Kobolde{/link} sind kein Ärgernis mehr, das man mit Fackeln vertreibt. Sie breiten sich aus, und sie graben tiefer, als je ein ehrlicher Bergmann zu graben wagte.]=],
		},
		{
			title = "Die Südgrenze",
			hint = "Kümmert Euch um die Sache mit Hogger.",
			text = [=[Lange Zeit erzählte man sich die Geschichten über {link:hogger}Hogger{/link} am Kaminfeuer. Dughan hörte auf, sie als Geschichten zu behandeln, als die Toten von den südlichen Höfen heimgebracht wurden.]=],
		},
		{
			title = "Der Sammler",
			hint = "Folgt dem gestohlenen Gold der Minen bis zu seinem Ende.",
			text = [=[Der aus den Minen gestohlene Goldstaub bleibt nicht bei den Kobolden. Er reist auf verborgenen Wegen zu einem Agenten der {link:defias-brotherhood}Defias{/link}, den man nur als den Sammler kennt. Als der Ring des Sammlers gefunden wird, trägt er das Zeichen der alten {link:stonemasons-guild}Steinmetzgilde{/link} von {link:stormwind-city}Stormwind{/link}. Da begreift Dughan, dass die Diebe von {link:elwynn-forest}Elwynn{/link} keine gewöhnlichen Banditen sind. Sie sind die Steinmetze, die Stormwind verraten hat.]=],
		},
	},
	mentions = {
		{
			text = [=[Meldet Euch in {link:goldshire}Goldhain{/link}, überbracht von {link:marshal-mcbride}Marschall McBride{/link}]=],
		},
		{ text = "Die {link:fargodeep-mine}Tiefenschachtmine{/link}" },
		{ text = "Die {link:jasperlode-mine}Jaspismine{/link}" },
		{
			text = [=[Die {link:westbrook-garrison}Weststromgarnison{/link} braucht Hilfe!]=],
		},
		{
			text = [=[Gesucht: {link:hogger}Hogger{/link}, ein Kopfgeld aus seiner Hand]=],
		},
		{
			text = [=[Eine fischige Gefahr, überbracht von {link:remy-two-times}Remy "Two Times"{/link}]=],
		},
		{ text = "Menschenjagd" },
		{ text = "Pssst! Wir jagen {link:kobolds}Kobolde{/link}" },
		{ text = "Bücherrückgabe" },
		{ text = "Seltene Bücher" },
	},
	bonds = {
		{ id = "marshal-mcbride", name = "Marschall McBride", note = "schickt ihm Rekruten" },
		{ id = "deputy-rainer", name = "Hilfssheriff Rainer", note = "hält die Weststromgarnison" },
		{ id = "guard-thomas", name = "Wachmann Thomas", note = "wacht über das Osttal" },
		{ id = "remy-two-times", name = "Remy \"Two Times\"", note = "bringt ihm Neuigkeiten" },
		{ id = "hogger", name = "Hogger", note = "Feind" },
	},
})

