Translate("deDE", "marshal-haggard", {
	title = "Marschall Haggard",
	subtitle = "Marschall von Stormwind im Ruhestand",
	found = "Sein Landhaus nahe dem Osttal",
	hint = "Besucht den alten Marschall, der nahe dem Osttal lebt.",
	allegiance = "Königreich Stormwind (im Ruhestand)",
	aliases = { "Haggard" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marschall Haggard diente {link:stormwind-city}Stormwind{/link} viele Jahre, bevor er sich in ein Landhaus nahe dem {link:eastvale-logging-camp}Osttal{/link} zurückzog. Seine Augen sind mit dem Alter trüb geworden, sein Stolz nicht. Er bewahrt noch das Abzeichen seines Amtes, und er kennt noch alte Geschichten, die jüngere Soldaten vergessen haben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Haggard ist eine lebende Erinnerung an das alte {link:stormwind-city}Stormwind{/link}. Sein Haus birgt auch den ersten Faden einer dunkleren Geschichte, die nach Osten in den {link:duskwood}Dämmerwald{/link} führt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er diente als Marschall von {link:stormwind-city}Stormwind{/link} bis zu seinem Ruhestand.
• Er kennt die alte Geschichte eines Mannes namens {link:stalvan-mistmantle}Stalvan{/link}, eine Geschichte, die mit einer versiegelten Kiste beginnt, die man in den Kanälen von Stormwind fand.]=],
		},
	},
	chapters = {
		{
			title = "Der Dieb im Dunkeln",
			hint = "Holt zurück, was dem alten Marschall genommen wurde.",
			text = [=[Eines Nachts kam ein Mann in einem Wappenrock von {link:stormwind-city}Stormwind{/link} an Haggards Tür. Im Dunkeln hielt der alte Marschall ihn für {link:marshal-dughan}Dughan{/link} und händigte ihm sein Abzeichen aus. Der Besucher war kein Marschall. Er war ein Dieb der {link:defias-brotherhood}Defias{/link} namens Dead-tooth Jack, und er verschwand vor Tagesanbruch mit dem Abzeichen.]=],
		},
		{
			title = "Die versiegelte Kiste",
			hint = [=[Bringt dem alten Marschall, was man in einer versiegelten Kiste in den Kanälen von Stormwind fand.]=],
			text = [=[Eine versiegelte Kiste, lange vergessen in den Kanälen von {link:stormwind-city}Stormwind{/link}, enthielt Papiere, die auf Marschall Haggard verwiesen. Als sie ihn erreichten, erkannte der alte Marschall den Namen, von dem sie sprachen. Es begann eine Geschichte, an die er sich lieber nicht erinnern würde: die Legende von {link:stalvan-mistmantle}Stalvan Mistmantle{/link}, ein Name, der im {link:duskwood}Dämmerwald{/link} noch immer voller Grauen geflüstert wird.]=],
		},
	},
	mentions = {
		{ text = "Marschall Haggard" },
		{ text = "Dead-tooth Jack" },
		{ text = "Die Legende von {link:stalvan-mistmantle}Stalvan{/link}" },
	},
	bonds = {
		{ id = "guard-thomas", name = "Wachmann Thomas", note = "hütet die nahe Brücke" },
		{ id = "marshal-dughan", name = "Marschall Dughan", note = "der Mann, den er zu sehen glaubte" },
	},
})

Translate("deDE", "guard-thomas", {
	title = "Wachmann Thomas",
	subtitle = "Wache der Brücke am Osttal",
