			title = "Zusammenfassung",
			text = [=[Wachmann Thomas hält die Brücke an der Straße zum {link:eastvale-logging-camp}Osttal{/link}. Er hat Männer an die wilden Tiere der östlichen Wälder verloren, und er fürchtet, weitere zu verlieren. Er beobachtet die Straße, zählt die Wölfe und schickt seine Berichte mit wachsender Sorge nach {link:goldshire}Goldhain{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thomas' Posten zeigt, wie sehr der Frieden Stormwinds zerfasert ist. Er glaubt, dass die Kämpfe bald {link:goldshire}Goldhain{/link} selbst erreichen werden.]=],
		},
