	},
	chapters = {
		{
			title = "Die verlorenen Wachen",
			hint = "Erfahrt, was aus den zwei vermissten Wachen wurde.",
			text = [=[Zwei von Thomas' Wachen zogen hinaus und kamen nicht zurück. Einer wurde halb aufgefressen im Wald gefunden. Der andere, Fußsoldat Rolf Hartford, wurde tot zwischen den {link:murlocs}Murlocs{/link} am See gefunden. Thomas schrieb ihre Namen in seinen Bericht und bat einmal mehr um Soldaten, die nie kamen.]=],
		},
	},
	mentions = {
		{ text = "Weitere Sorgen" },
