	},
	bonds = {
		{ id = "marshal-dughan", name = "Marschall Dughan", note = "empfängt seine Berichte" },
		{ id = "marshal-haggard", name = "Marschall Haggard", note = "lebt in der Nähe" },
	},
})

Translate("deDE", "theocritus", {
	title = "Theocritus",
	subtitle = "Hochmagier des Turms von Azora",
	found = "Das oberste Stockwerk des Turms von Azora",
	hint = [=[Steigt den Turm von Azora hinauf und sprecht mit seinem Herrn.]=],
	allegiance = "Turm von Azora",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Theocritus ist der Herr des Turms von {link:tower-of-azora}Azora{/link}. Er ist ein Magier von großer Gelehrsamkeit und wenig Geduld, dem {link:gnomes}Gnome{/link} dienen, die seine Instrumente pflegen. Seine größte Sorge liegt weit im Osten: der Hexenmeister {link:morganth}Morganth{/link}, der im {link:tower-of-ilgalar}Turm von Ilgalar{/link} im {link:redridge-mountains}Rotkammgebirge{/link} haust.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Theocritus ist einer der wenigen, die die dunklen Mächte beobachten, die sich jenseits der Grenzen Elwynns sammeln. Während die Marschälle die Straßen bewachen, wacht er über das, was man nicht mit Schwertern bekämpfen kann.]=],
		},
		{
			title = "Taten",
			text = [=[• Er beobachtet {link:morganth}Morganth{/link} durch das spähende Auge von {link:tower-of-azora}Azora{/link}.
• Er sucht Morganths Jagd nach einem alten Relikt namens {red:scythe-of-elune}Sense von Elune{/red} zu vereiteln.]=],
		},
	},
	chapters = {
		{
			title = "Das Auge von Azora",
			hint = "Helft dem Hochmagier, seinen Rivalen zu beobachten.",
			text = [=[Um in den Turm von {link:tower-of-ilgalar}Ilgalar{/link} zu sehen, braucht das Auge von {link:tower-of-azora}Azora{/link} einen Fokuspunkt nahe seinen Mauern. Theocritus schickt eine Glyphe nach Osten, die auf einer alten Löwenstatue neben dem Turm des Hexenmeisters angebracht werden soll. Durch sie kann das Auge dorthin blicken, wo {link:morganth}Morganth{/link} glaubt, dass niemand zusieht.]=],
