		},
	},
	chapters = {
		{
			title = "Die angeknabberte Bibliothek",
			hint = [=[Bringt dem Hüter der Bibliothek der Abtei ein gestohlenes Buch zurück.]=],
			text = [=[Das erste Buch kam halb zerkaut zurück, fallen gelassen von einem {link:kobolds}Kobold{/link} im Tal. Paxton erkannte es sofort. Die Kobolde stahlen nicht nur Kerzen und Erz. Sie stahlen Wissen, und sie hatten keine Ahnung, was sie damit anfangen sollten.]=],
		},
		{
			title = "Die letzten der vermissten Bücher",
			hint = "Holt die letzten Bücher auf Bruder Paxtons Liste zurück.",
			text = [=[Die Spur der gestohlenen Bücher führte vom Echokamm zum {link:fargodeep-mine}Tiefenschacht{/link} und zuletzt zur {link:jasperlode-mine}Jaspismine{/link}. Dort hatten die {link:kobolds}Kobolde{/link} die Bücher nicht bloß gehortet. Ein Koboldmeister hatte begonnen, sie zu lesen, und was er lernte, ließ ihn die Erde selbst seinem Willen beugen.]=],
		},
	},
	mentions = {
		{ text = "Angeknabbertes Buch" },
		{ text = "Freche Nager" },
		{ text = "Bücherverzeichnis" },
		{ text = "Bergbauberater" },
		{ text = "Seltene Bücher, in seine Hände zurückgegeben" },
