		{ id = "marshal-mcbride", name = "Marschall McBride", note = "jagt die Bücherdiebe" },
		{ id = "marshal-dughan", name = "Marschall Dughan", note = "verfolgt die Diebe über Nordhain hinaus" },
	},
})

