Translate("deDE", "camping", {
	title = "Lagern",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Lagern ist die alte Kunst der Straße: in der Wildnis ein Feuer zu entfachen, es zu teilen und neben ihm zu ruhen, bevor die Reise weitergeht. Reisende in ganz {link:azeroth}Azeroth{/link} wussten immer, dass eine Nacht an einem guten Feuer den Unterschied ausmachen kann zwischen dem Erreichen der nächsten Stadt und dem Nie-Ankommen.]=],
		},
		{
			title = "Das Feuer und die Handwerke",
			text = [=[Ein Lager beginnt mit einem Lagerfeuer, entfacht von jenen, die die Kunst des Kochens beherrschen. Andere Reisende können dann etwas hinzufügen, jeder nach dem Handwerk, das er kennt. Ein Schmied stellt einen Schleifstein auf. Ein Lederer errichtet ein Zelt. Ein Alchemist, ein Verzauberer, ein Bergmann oder ein Schneider bringt jeweils etwas Eigenes: einen Brunnen des Manas, eine verzauberte Laute, einen Magnetstein, ein Banner seines Volkes. Die größten dieser Werke werden nach Plänen gebaut, die die Meister jedes Handwerks hüten, und man sagt, dass manche dieser Pläne in den Händen gefährlicher Feinde liegen.]=],
		},
		{
			title = "Der Brauch des Feuers",
			text = [=[Nach altem Brauch fügt jeder Reisende einem gemeinsamen Feuer ein einziges Werk hinzu, und kein Handwerk wird zweimal neben dieselben Flammen gesetzt. Wer eine Weile an einem solchen Feuer sitzt, erhebt sich erfrischt, und er trägt dessen Segen stundenlang mit sich auf der Straße.]=],
		},
	},
})
